If(
    CountRows(
        Filter(
            glr_Pots_1.AllItems,
            !IsBlank(Trim(CantidadMats.Text)) &&
            IsMatch(CantidadMats.Text, "^\-?\d+(\.\d+)?$") &&
            Value(CantidadMats.Text) < 0
        )
    ) > 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Se digito cantidades negativas, no se puede guardar."
        }
    ),

    If(
        CountRows(
            Filter(
                glr_Pots_1.AllItems,
                Value(CantidadMats.Text) = 0 && IsBlank(Trim(txtObservacion.Text))
            )
        ) > 0,
        UpdateContext(
            {
                MostrarAviso: true,
                mensajeNotificacion: "Debe escribir una observación para los materiales con cantidad 0."
            }
        ),

        ClearCollect(
            tempTableCurrent,
            ForAll(
                glr_Pots_1.AllItems,
                {
                    Item: ThisRecord.item,
                    Description: ThisRecord.description,
                    QtyOrdered: ThisRecord.qty_ordered,
                    Cantidad: Value(CantidadMats.Text),
                    POT: ThisRecord.po_num,
                    Observacion: txtObservacion.Text
                }
            )
        );
        Collect(PotsSeleccionadas, tempTableCurrent);
        UpdateContext(
            {
                MostrarAviso: true,
                mensajeNotificacion: "Materiales agregados correctamente.",
                Materiales: false
            }
        );
        Reset(txtObservacion);
        Reset(CantidadMats)
    )
)

If(
    CountRows(
        Filter(
            glr_Pots_2.AllItems,
            IsMatch(
                CantidadMats.Text,
                "^\-?\d+(\.\d+)?$"
            ) && Value(CantidadMats.Text) < 0
        )
    ) > 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Se digitó una cantidad negativa. No se puede guardar."
        }
    ),
    CountRows(
        Filter(
            glr_Pots_2.AllItems,
            IsMatch(
                CantidadMats.Text,
                "^\-?\d+(\.\d+)?$"
            ) && Value(CantidadMats.Text) > Value(txtCantidadDisponible.Text)
        )
    ) > 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Alguna cantidad supera la cantidad disponible. Revise y corrija."
        }
    ),
    CountRows(
        Filter(
            glr_Pots_2.AllItems,
            IsMatch(
                CantidadMats.Text,
                "^\-?\d+(\.\d+)?$"
            ) && Value(CantidadMats.Text) < Value(txtCantidadDisponible.Text) && IsBlank(Trim(txtObservacion.Text))
        )
    ) > 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Faltan observaciones para materiales con cantidad menor a la disponible."
        }
    ),
    CountRows(
        Filter(
            glr_Pots_2.AllItems,
            IsMatch(
                CantidadMats.Text,
                "^\-?\d+(\.\d+)?$"
            ) && Value(CantidadMats.Text) <> 0
        )
    ) = 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Todas las cantidades están en 0. No hay materiales para agregar."
        }
    ),
    ClearCollect(
        tempTableCurrent,
        ForAll(
            glr_Pots_2.AllItems,
            {
                Item: ThisRecord.item,
                Description: ThisRecord.description,
                QtyOrdered: ThisRecord.qty_ordered,
                Cantidad: Value(CantidadMats.Text),
                POT: ThisRecord.po_num,
                Observacion: txtObservacion.Text
            }
        )
    );
    Collect(
        PotsSeleccionadas,
        tempTableCurrent
    );
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Materiales agregados correctamente.",
            Materiales: false,
            reset: true
        }
    );
    UpdateContext({reset: false})
)

UpdateContext({
